window.S3_UI=(()=>{const S=window.S3_STRINGS;function el(tag,cls,text){const n=document.createElement(tag);if(cls)n.className=cls;if(text!==undefined)n.textContent=text;return n;}function chip(label){const b=el('button','chip');b.type='button';b.setAttribute('aria-pressed','false');const check=el('span','chip-check','✓');check.setAttribute('aria-hidden','true');b.append(check,el('span','',label));return b;}function card(e,href,prefix='catalog'){const live=e.status==='live',c=el(live?'a':'article','card '+(live?'card--playable':'card--preparing'));c.dataset.id=e.id;const title=prefix+'-'+e.id+'-title',summary=prefix+'-'+e.id+'-summary';if(live){c.href=href||e.href;c.setAttribute('aria-labelledby',title);c.setAttribute('aria-describedby',summary);}const preview=el('div','preview'+(live?'':' preview--plate'));if(live){const img=el('img');img.src=e.thumb;img.alt=e.alt;img.width=1600;img.height=1000;preview.append(img);}else{preview.dataset.pattern=e.topics[0];preview.setAttribute('aria-hidden','true');preview.append(el('span','plate-caption',window.S3_TOPICS.find(t=>t.id===e.topics[0]).label+' · '+S.preparing),el('span','plate-mark',e.mark));}const body=el('div','card-body'),meta=el('div','meta');meta.append(el('span','badge '+(live?'badge--playable':''),live?S.playable:S.preparing),el('span','',e.layer));if(e.spec)meta.append(el('span','',e.spec));const h=el('h2','',e.title),desc=el('p','summary',e.summary);h.id=title;desc.id=summary;const foot=el('div','card-bottom');foot.append(el('span','',e.topics.map(id=>window.S3_TOPICS.find(t=>t.id===id).label).join(' · ')),el('span',live?'card-cta':'preparing-note',live?S.open:S.ready));body.append(meta,h,desc,foot);c.append(preview,body);return c;}return{el,chip,card};})();
